		protected IAutoRatingWarehouseInfo AutoRatingWarehouseInfo;
		protected IManualRateSelectionSupporter ManualRateSelectionSupporter;

		/// <summary>
		/// A private class for handling of the setting/getting
		/// </summary>
		class Prop<T>
		{
			bool isSet;
			T storedValue;
			readonly string propertyName;

			public Prop(string underlyingPropertyName)
			{
				propertyName = underlyingPropertyName;
			}

			public T CurrentValue => storedValue;

			public void Setter(bool valuesCanBeSet, T newValue)
			{
				if (valuesCanBeSet)
				{
					storedValue = newValue;
					isSet = true;
				}
				else
				{
					throw new NotSupportedException("You cannot set values on this object unless ValuesCanBeSet is true.");
				}
			}

			public T Getter(IAutoRating autoRating)
			{
				if (!isSet && autoRating != null)
				{
					storedValue = GetDefaultValue(autoRating);
					isSet = true;
				}
				return storedValue;
			}

			T GetDefaultValue(object target)
			{
				PropertyInfo propertyInfo = GetPropertyInfo(ref target, propertyName);
				return (T)propertyInfo.GetValue(target, null);
			}

			static PropertyInfo GetPropertyInfo(ref object target, string propertyName)
			{
				string[] array = propertyName.Split(new char[1] { '.' }, StringSplitOptions.RemoveEmptyEntries);
				PropertyInfo property = target.GetType().GetProperty(array[0]);
				if (array.Length == 1)
				{
					return property;
				}

				string propertyName2 = string.Join(".", array.Skip(1));
				target = property.GetValue(target, null);
				return GetPropertyInfo(ref target, propertyName2);
			}
		}

		/// <summary>
		/// Designed to support as a backing field to cache the methods return values based on Cost or Revenue Autorating
		/// </summary>
		struct CostRevenueBasedProp<T>
		{
			public CostRevenueBasedProp(Func<CostSell, T> getter)
				=> Getter = Argument.NotNull(getter, nameof(getter));

			public T Get(CostSell costOrSell)
				=> costOrSell == CostSell.Cost ? GetCostBasedValue() : GetRevenueBasedValue();

			T GetCostBasedValue()
			{
				if (!isCostBasedValueSet)
				{
					costBasedValue = Getter(CostSell.Cost);
					isCostBasedValueSet = true;
				}

				return costBasedValue;
			}

			T GetRevenueBasedValue()
			{
				if (!isRevenueBasedValueSet)
				{
					revenueBasedValue = Getter(CostSell.Revenue);
					isRevenueBasedValueSet = true;
				}

				return revenueBasedValue;
			}

			Func<CostSell, T> Getter { get; }

			bool isCostBasedValueSet;
			T costBasedValue;

			bool isRevenueBasedValueSet;
			T revenueBasedValue;
		}
	}
}
